-- Dancing characters move into the database (2026-09-23, Peter).
-- Every dancing character's drawing now lives in public.dancers and the app
-- pulls it from there. Until today all 24 were hard-coded in
-- src/components/Critters.jsx; that file now reads this table instead.
--
-- svg = the shapes for one character on the shared 200x200 stage, with no
-- <svg> wrapper. The app adds the wrapper, the shadow and the dance moves
-- (the nw-* class names in the markup say which part moves how).
-- kind: animal = one of the twelve a kid can have as their animal;
--       guest  = a guest dancer.
-- sort_order keeps the order the app has always used. Done marks pick a
-- character by position, so this order keeps every existing pick the same.
-- The markup was rendered from the old React code with react-dom/server,
-- so it is exactly what the browser drew before the move.
--
-- Readable by every signed-in login, the Family Hub included (the Family
-- pages show these), so this table deliberately has no zz_block_family_login
-- policy. Only admins can change rows.

CREATE TABLE IF NOT EXISTS public.dancers (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agency_id  uuid NOT NULL DEFAULT '126794dd-25ff-47d2-a436-724499733365'::uuid,
  key        text NOT NULL UNIQUE,
  label      text NOT NULL,
  kind       text NOT NULL CHECK (kind IN ('animal', 'guest')),
  sort_order integer NOT NULL,
  svg        text NOT NULL,
  is_active  boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- Drawing only: no scripts, no event handlers, no <svg> wrapper.
  CONSTRAINT dancers_svg_is_drawing_only CHECK (
    svg !~* '<\s*script' AND svg !~* '\son[a-z]+\s*=' AND svg !~* 'javascript:'
    AND svg !~* '<\s*/?\s*svg[\s>]'
  )
);

COMMENT ON TABLE public.dancers IS 'The dancing characters used in celebrations, done marks and the Inventory list. svg is one character''s drawing on a 200x200 stage, no <svg> wrapper; the app adds the frame, shadow and dance moves.';
COMMENT ON COLUMN public.dancers.kind IS 'animal = one a kid can have as their animal; guest = a guest dancer.';
COMMENT ON COLUMN public.dancers.sort_order IS 'The order the app lists them in. Done marks pick by position, so a new order or a new count changes which character each done mark shows.';

DROP TRIGGER IF EXISTS dancers_set_updated_at ON public.dancers;
CREATE TRIGGER dancers_set_updated_at BEFORE UPDATE ON public.dancers
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.dancers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS dancers_read ON public.dancers;
CREATE POLICY dancers_read ON public.dancers FOR SELECT TO authenticated
  USING (agency_id = '126794dd-25ff-47d2-a436-724499733365');
DROP POLICY IF EXISTS dancers_admin_all ON public.dancers;
CREATE POLICY dancers_admin_all ON public.dancers FOR ALL TO authenticated
  USING (agency_id = '126794dd-25ff-47d2-a436-724499733365' AND (SELECT public.is_agency_admin()))
  WITH CHECK (agency_id = '126794dd-25ff-47d2-a436-724499733365' AND (SELECT public.is_agency_admin()));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.dancers TO authenticated;

