ALTER TABLE public.family_kids ADD CONSTRAINT family_kids_animal_fkey
  FOREIGN KEY (animal) REFERENCES public.dancers(key) ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE public.family_kids DROP CONSTRAINT IF EXISTS family_kids_favorite_animal_fkey;
ALTER TABLE public.family_kids ADD CONSTRAINT family_kids_favorite_animal_fkey
  FOREIGN KEY (favorite_animal) REFERENCES public.dancers(key) ON UPDATE CASCADE ON DELETE SET NULL;
